#include <observation/observation.hpp>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <unistd.h>
namespace rebuntu::observation {static std::string id(std::string_view d,std::string_view k){return std::string(d)+"\0"+std::string(k);}void StateView::observe(Observation o){auto k=id(o.domain,o.key);auto it=current_.find(k);if(it!=current_.end()&&it->second.value!=o.value)history_.push_back({it->second,o,o.provenance.observed_at});current_[k]=std::move(o);}std::optional<Observation>StateView::get(std::string_view d,std::string_view k)const{auto i=current_.find(id(d,k));return i==current_.end()?std::optional<Observation>{}:i->second;}std::vector<Observation>StateView::domain(std::string_view d)const{std::vector<Observation>o;for(auto&[k,v]:current_)if(v.domain==d)o.push_back(v);return o;}bool StateView::fresh(std::string_view d,std::string_view k,std::chrono::seconds age)const{auto o=get(d,k);return o&&std::chrono::system_clock::now()-o->provenance.observed_at<=age;}
std::vector<Observation>observe_procfs(){std::vector<Observation>o;Provenance p{"procfs",Quality::authoritative};std::ifstream f("/proc/loadavg");std::string load;if(f>>load)o.push_back({"cpu","load1",load,p});std::ifstream m("/proc/meminfo");std::string key,val,unit;while(m>>key>>val>>unit){if(key=="MemTotal:"||key=="MemAvailable:")o.push_back({"memory",key.substr(0,key.size()-1),val,p});}o.push_back({"process","self_pid",std::to_string(::getpid()),p});return o;}std::vector<Observation>observe_filesystem(std::string_view path){std::vector<Observation>o;std::error_code ec;auto s=std::filesystem::space(path,ec);if(!ec){Provenance p{"std::filesystem",Quality::authoritative};o.push_back({"filesystem","capacity",std::to_string(s.capacity),p});o.push_back({"filesystem","available",std::to_string(s.available),p});}return o;}
}